// Normalize Ollama output. If caller asked for json format, parse it.
const item = $input.first().json;
const raw = item.response ?? '';
let parsed = null;
const wantsJson = ($('When Executed by Another Workflow').first().json.format === 'json');
if (wantsJson) {
  try { parsed = JSON.parse(raw); } catch (e) {
    // best-effort: pull the first {...} block
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) { try { parsed = JSON.parse(m[0]); } catch (_) {} }
  }
}
return [{ json: { response: raw, parsed, model: item.model, done: item.done } }];
